100:function makePrompt(input, imagePath) {
101:  const componentVocabulary = [
102:    "Text",
103:    "Button",
104:    "TextInput",
105:    "Textarea",
106:    "Checkbox",
107:    "Select",
108:    "Image",
109:    "Card",
110:    "List",
111:    "Modal",
112:    "Tabs",
113:    "Navbar",
114:  ];
115:  const behaviorVocabulary = [
116:    "setState",
117:    "filter",
118:    "sort",
119:    "validate",
120:    "open",
121:    "close",
122:    "navigate",
123:    "fetch",
124:    "create",
125:    "update",
126:    "delete",
127:    "visibility",
128:    "custom",
129:  ];
130:  const graph = JSON.stringify(input.graph ?? {}, null, 2);
131:  const canvas = input.canvas ?? { width: 1024, height: 768 };
132:  const strokeCount = Array.isArray(input.strokes) ? input.strokes.length : 0;
133:
134:  return `You compile a hand-drawn sketch into a working client-side app.
135:
136:Inspect the attached PNG at ${imagePath}. It shows, on a paper background:
137:- Thin grey boxes labeled "<id> · <Type> · <label>" — components that ALREADY
138:  exist in the app graph. Never recreate these.
139:- Black ink — a new batch of ${strokeCount} strokes the user just drew. This is
140:  the only thing you are being asked to interpret.
141:
142:Canvas coordinates are ${canvas.width} by ${canvas.height}.
143:
144:Current app graph:
145:${graph}
146:
147:The new ink may contain new UI shapes, wiring between existing components,
148:handwritten notes describing logic, or any mix of the three. Work out which and
149:return the corresponding new components and new behavior edges together.
150:
151:Return only the structured response required by the supplied schema.
152:
153:## Components
154:
155:- Allowed types: ${componentVocabulary.join(", ")}.
156:- Use the drawn element's pixel bounding box for x, y, width, height.
157:- Transcribe handwritten labels. A digit or symbol inside a small box is that
158:  button's label.
159:- A long low rectangle with prompt-like text is TextInput. A compact labeled
160:  rectangle is Button. A wide box holding a number or intended to show output is
161:  Text. Repeated rows are List. A small square beside text is Checkbox.
162:- stateKey binds a component to one app-state value:
163:  - a Text that displays a running value gets that value's key (e.g. "display")
164:  - a TextInput gets the key its typed value should be stored under
165:  - a Button almost always has stateKey ""
166:- confidence is 0 to 1.
167:
168:## Behaviors
169:
170:Each edge is one handler bound to one component's event.
171:
172:- source must be an existing or newly returned component id.
173:- target is the component the behavior visibly affects; use "" when the logic
174:  only writes app state.
175:- triggerEvent is normally click, change, or submit.
176:- actionType must be one of: ${behaviorVocabulary.join(", ")}.
177:- One handwritten note may justify MANY edges. "digits append to the display"
178:  over a keypad means one edge per digit button. Emit them all.
179:- tests are short behavioral assertions, not executable test files.
180:- If a mark is ambiguous, omit it. Never invent UI or wiring that is not drawn.
181:
182:## Handler contract — read carefully
183:
184:handler is a JavaScript statement body executed in the browser. It is REAL code
185:that runs; it is not a description. These names are in scope and nothing else:
186:
187:  state          plain object of all current app state
188:  get(key)       read one state value
189:  set(key, val)  write one state value
190:  event          { type, value, componentId } — value is the typed text for
191:                 inputs, or the button label for clicks
192:  self           the component that fired
193:  target         the target component, or null
194:  num(v)         coerce anything to a finite number (blank/garbage becomes 0)
195:
196:No imports, no await, no fetch, no DOM, no timers, no console. Do not declare a
197:function — write the statements directly. Multiple handlers triggered by the
198:same event run in order against the same state, and the UI re-renders once.
199:
200:Write every string literal in handler code with SINGLE quotes. A handler is
201:carried inside a JSON string, and single quotes keep that escaping trivial.
202:
203:initialState declares the starting values every handler can rely on. Return it
204:as key/value pairs; values are strings and handlers coerce with num() as needed.
205:
206:## Worked example — an arithmetic calculator
207:
208:Given a display box and drawn keys, correct output looks like:
209:
210:component: { id: "display", type: "Text", stateKey: "display", label: "0", … }
211:component: { id: "key7", type: "Button", stateKey: "", label: "7", … }
212:
213:initialState: [ {key:"display",value:"0"}, {key:"acc",value:"0"},
214:                {key:"op",value:""}, {key:"fresh",value:"1"} ]
215:
216:edge for the "7" key:
217:  source "key7", target "display", triggerEvent "click", actionType "setState"
218:  handler:
219:    const d = get('fresh') === '1' ? '' : String(get('display') ?? '');
220:    set('display', (d === '0' ? '' : d) + '7');
221:    set('fresh', '0');
222:
223:edge for the "+" key:
224:  source "keyPlus", target "display", triggerEvent "click", actionType "setState"
225:  handler:
226:    set('acc', String(num(get('display'))));
227:    set('op', '+');
228:    set('fresh', '1');
229:
230:edge for the "=" key:
231:  source "keyEquals", target "display", triggerEvent "click", actionType "custom"
232:  handler:
233:    const a = num(get('acc'));
234:    const b = num(get('display'));
235:    const op = String(get('op') ?? '');
236:    let r = b;
237:    if (op === '+') r = a + b;
238:    else if (op === '-') r = a - b;
239:    else if (op === '*') r = a * b;
240:    else if (op === '/') r = b === 0 ? 0 : a / b;
241:    set('display', String(Math.round(r * 1e10) / 1e10));
242:    set('op', '');
243:    set('fresh', '1');
244:
245:edge for the "C" key:
246:  source "keyClear", target "display", triggerEvent "click", actionType "setState"
247:  handler:
248:    set('display', '0'); set('acc', '0'); set('op', ''); set('fresh', '1');
249:
250:Follow that shape for whatever the user actually drew. Write handlers that
251:genuinely work when clicked, not placeholders.
252:`;
253:}
