function makePrompt(input, imagePath) {
  const componentVocabulary = [
    "Text",
    "Button",
    "TextInput",
    "Textarea",
    "Checkbox",
    "Select",
    "Image",
    "Card",
    "List",
    "Modal",
    "Tabs",
    "Navbar",
  ];
  const behaviorVocabulary = [
    "setState",
    "filter",
    "sort",
    "validate",
    "open",
    "close",
    "navigate",
    "fetch",
    "create",
    "update",
    "delete",
    "visibility",
    "custom",
  ];
  const graph = JSON.stringify(input.graph ?? {}, null, 2);
  const canvas = input.canvas ?? { width: 1024, height: 768 };
  const strokeCount = Array.isArray(input.strokes) ? input.strokes.length : 0;

  return `You compile a hand-drawn sketch into a working client-side app.

Inspect the attached PNG at ${imagePath}. It shows, on a paper background:
- Thin grey boxes labeled "<id> · <Type> · <label>" — components that ALREADY
  exist in the app graph. Never recreate these.
- Black ink — a new batch of ${strokeCount} strokes the user just drew. This is
  the only thing you are being asked to interpret.

Canvas coordinates are ${canvas.width} by ${canvas.height}.

Current app graph:
${graph}

The new ink may contain new UI shapes, wiring between existing components,
handwritten notes describing logic, or any mix of the three. Work out which and
return the corresponding new components and new behavior edges together.

Return only the structured response required by the supplied schema.

## Components

- Allowed types: ${componentVocabulary.join(", ")}.
- Use the drawn element's pixel bounding box for x, y, width, height.
- Transcribe handwritten labels. A digit or symbol inside a small box is that
  button's label.
- A long low rectangle with prompt-like text is TextInput. A compact labeled
  rectangle is Button. A wide box holding a number or intended to show output is
  Text. Repeated rows are List. A small square beside text is Checkbox.
- stateKey binds a component to one app-state value:
  - a Text that displays a running value gets that value's key (e.g. "display")
  - a TextInput gets the key its typed value should be stored under
  - a Button almost always has stateKey ""
