import { spawn } from "node:child_process";
import { networkInterfaces } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const SERVER_DIR = dirname(fileURLToPath(import.meta.url));
const PROJECT_DIR = dirname(SERVER_DIR);
const npmCommand = process.platform === "win32" ? "npm.cmd" : "npm";

const bridge = spawn(process.execPath, [join(SERVER_DIR, "agent-bridge.mjs")], {
  cwd: PROJECT_DIR,
  env: process.env,
  stdio: "inherit",
});

const web = spawn(npmCommand, ["run", "dev:web"], {
  cwd: PROJECT_DIR,
  env: process.env,
  stdio: "inherit",
});

const networkUrls = Object.values(networkInterfaces())
  .flatMap((entries) => entries ?? [])
  .filter((entry) => entry.family === "IPv4" && !entry.internal)
  .map((entry) => `http://${entry.address}:3000/`);

for (const url of networkUrls) {
  console.log(`  iPad:        ${url}`);
}

bridge.on("exit", (code) => {
  if (code && code !== 0) {
    console.warn(
      `Agent bridge stopped with status ${code}; local shape matching remains available.`,
    );
  }
});

web.on("exit", (code) => {
  if (!bridge.killed) bridge.kill("SIGTERM");
  process.exit(code ?? 0);
});

function shutdown() {
  if (!web.killed) web.kill("SIGTERM");
  if (!bridge.killed) bridge.kill("SIGTERM");
}

process.on("SIGINT", shutdown);
process.on("SIGTERM", shutdown);

