                  ? "Bridge offline — the local shape matcher will be used."
                  : agentStatus.available[engine]
                    ? `${engine} is ready`
                    : `${engine} is not on PATH — the local shape matcher will be used.`}
              </div>
              <button
                type="button"
                className="secondary-button"
                onClick={() => void refreshAgentStatus()}
              >
