    if (pending.length === 0) {
      flash("Draw something first.", 2200);
      return;
    }

    setProcessing(true);
    setStatusText(
      graphRef.current.components.length
        ? "Reading the canvas…"
        : "Reading the sketch…",
    );
    const pendingIds = new Set(pending.map((stroke) => stroke.id));
    let response: ProcessResponse | null = null;
    let failure = "";

    try {
      const image = await captureCanvasImage();
      const request = await fetch("/agent-api/process", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          engine,
          model: models[engine],
          canvas: canvasSize,
          image,
          strokes: pending.map((stroke) => ({
            ...stroke,
            points:
              stroke.points.length > 160
                ? stroke.points.filter(
                    (_, index) =>
                      index % Math.ceil(stroke.points.length / 160) === 0,
                  )
                : stroke.points,
          })),
          graph: graphRef.current,
        }),
      });
      if (!request.ok) {
        const error = (await request.json().catch(() => null)) as {
          error?: string;
        } | null;
        throw new Error(error?.error || `Agent returned ${request.status}`);
      }
      response = (await request.json()) as ProcessResponse;
    } catch (error) {
      // Surface why we fell back — a bad model name and an offline bridge used
      // to look identical from the canvas.
      failure = error instanceof Error ? error.message : "Processing failed.";
      response = localResponse(pending);
    } finally {
      setProcessing(false);
      void refreshAgentStatus();
    }

    if (
      response.engine !== "local" &&
      response.components.length === 0 &&
      response.edges.length === 0
    ) {
      const fallback = localResponse(pending);
      if (fallback.components.length > 0 || fallback.edges.length > 0) {
        response = fallback;
      }
    }

    applyProcessResponse(pendingIds, response);
    if (failure) flash(`${engine} unavailable — ${failure}`, 6000);
  }, [
    applyProcessResponse,
    canvasSize,
    captureCanvasImage,
    engine,
    flash,
    localResponse,
    mode,
    models,
    processing,
    refreshAgentStatus,
  ]);

  const resetRun = useCallback(() => {
    setAppState({ ...graphRef.current.initialState });
  }, []);

  const enterMode = useCallback(
    (next: WorkspaceMode) => {
      setMode(next);
      setSelectedId(null);
      if (sidePanel === "component") setSidePanel(null);
      // Every Run starts from the declared initial state, so the app behaves the
      // same way each time you go to use it.
      if (next === "run") setAppState({ ...graphRef.current.initialState });
    },
    [sidePanel],
  );

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key === "Enter") {
        event.preventDefault();
        void processSketch();
      }
      if (
        (event.metaKey || event.ctrlKey) &&
        event.key.toLowerCase() === "z" &&
        !event.shiftKey
      ) {
        event.preventDefault();
        undo();
      }
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "r") {
        event.preventDefault();
        enterMode(mode === "run" ? "draw" : "run");
      }
      if (event.key === "Escape") {
        setSidePanel(null);
        setSelectedId(null);
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [enterMode, mode, processSketch, undo]);

  /** Runs the behaviors bound to one component event. */
  const fire = useCallback(
    (
      component: AppComponent,
      eventName: string,
      value: string | number | boolean,
    ) => {
      const edges = matchingEdges(
        graphRef.current.bindings,
        component.id,
        eventName,
      );
      if (edges.length === 0) return;

      const result = runHandlers(
        edges,
        graphRef.current.components,
        appStateRef.current,
        { type: eventName, value, componentId: component.id },
      );
      appStateRef.current = result.state;
      setAppState(result.state);

…
    },
…
  );

