async function findExecutable(name) {
  const pathEntries = (process.env.PATH || "").split(delimiter);
  for (const entry of pathEntries) {
    if (!entry) continue;
    const candidate = join(entry, name);
    try {
      await access(candidate, fsConstants.X_OK);
