const beginStroke = (event: ReactPointerEvent<SVGSVGElement>) => {
  if (mode === "run" || processing || !event.isPrimary) return;
  event.preventDefault();
  // Capture is an optimization, not a requirement: it throws when the pointer
  // is already gone, and losing the stroke over that would be worse.
  try {
    event.currentTarget.setPointerCapture(event.pointerId);
  } catch {
    // Keep drawing without capture.
  }
  const point = pointFromEvent(event);
  // A press that lands on a recognized component grabs it: the gesture is a
  // move unless the release lands on another component, which makes it a
  // wiring arrow. The ink is kept either way so the arrow can be committed.
  const hit = [...graphRef.current.components]
    .reverse()
    .find((component) => hitTest(point, component, 0));
  if (hit) {
    dragRef.current = {
      id: hit.id,
      origin: point,
      bounds: { ...hit.bounds },
      moved: false,
      points: [point],
    };
    return;
  }
  const stroke: InkStroke = {
    id: createId("stroke"),
    points: [point],
    processed: false,
  };
  draftRef.current = stroke;
  setDraftStroke(stroke);
};

const continueStroke = (event: ReactPointerEvent<SVGSVGElement>) => {
  const drag = dragRef.current;
  if (drag) {
    event.preventDefault();
    const native = event.nativeEvent;
    const coalesced =
      typeof native.getCoalescedEvents === "function"
        ? native.getCoalescedEvents()
        : [];
    const points = (coalesced.length > 0 ? coalesced : [native]).map(
      pointFromEvent,
    );
    drag.points.push(...points);
    const point = points[points.length - 1];
    const dx = point.x - drag.origin.x;
    const dy = point.y - drag.origin.y;
    // Under the threshold this is still a tap, not a move.
    if (!drag.moved && Math.hypot(dx, dy) < 6) return;
    if (!drag.moved) {
      drag.moved = true;
      saveHistory();
    }
    setGraph((current) => ({
      ...current,
      components: current.components.map((component) =>
        component.id === drag.id
          ? {
              ...component,
              bounds: {
                x: clamp(
                  drag.bounds.x + dx,
                  0,
                  Math.max(0, canvasSize.width - drag.bounds.width),
                ),
                y: clamp(
                  drag.bounds.y + dy,
                  0,
                  Math.max(0, canvasSize.height - drag.bounds.height),
                ),
                width: drag.bounds.width,
                height: drag.bounds.height,
