import { readFile } from "node:fs/promises";

const graph = JSON.parse(
  await readFile(
    "/Users/francip/src/magicapp/tests/fixtures/calculator.graph.json",
    "utf8",
  ),
);
const image =
  "data:image/png;base64," +
  (await readFile("/tmp/omp-test/sketch.png")).toString("base64");

// The new ink: a closed box for the ± key and an arrow up to the display.
const box = [];
const x0 = 750, y0 = 640, x1 = 850, y1 = 720;
for (let x = x0; x <= x1; x += 10) box.push({ x, y: y0, pressure: 0.5 });
for (let y = y0; y <= y1; y += 10) box.push({ x: x1, y, pressure: 0.5 });
for (let x = x1; x >= x0; x -= 10) box.push({ x, y: y1, pressure: 0.5 });
for (let y = y1; y >= y0; y -= 10) box.push({ x: x0, y, pressure: 0.5 });
const arrow = [];
for (let y = 640; y >= 130; y -= 20) arrow.push({ x: 800, y, pressure: 0.5 });

const body = {
  engine: "omp",
  model: "",
  canvas: { width: 1024, height: 768 },
  image,
  strokes: [
    { id: "stroke-box", points: box, processed: false },
    { id: "stroke-arrow", points: arrow, processed: false },
  ],
  graph,
};

const started = Date.now();
const response = await fetch("http://127.0.0.1:8787/api/process", {
  method: "POST",
  headers: { "content-type": "application/json" },
  body: JSON.stringify(body),
});
const seconds = ((Date.now() - started) / 1000).toFixed(1);
const value = await response.json();
console.log(`status=${response.status} time=${seconds}s`);
console.log(JSON.stringify(value, null, 2));

